template:
// Subsets / combinations (order does not matter): use a start index.
void subsets(const vector<int>& a, int start, vector<int>& path, vector<vector<int>>& out) {
    out.push_back(path);                              // every node of the tree is an answer
    for (int i = start; i < (int)a.size(); ++i) {
        if (i > start && a[i] == a[i-1]) continue;    // skip duplicates (a must be sorted)
        path.push_back(a[i]);                         // choose
        subsets(a, i + 1, path, out);                 // explore
        path.pop_back();                              // un-choose
    }
}

// Permutations (order matters): track used[].
void permute(const vector<int>& a, vector<bool>& used, vector<int>& path, vector<vector<int>>& out) {
    if (path.size() == a.size()) { out.push_back(path); return; }   // leaf
    for (int i = 0; i < (int)a.size(); ++i) {
        if (used[i]) continue;
        if (i > 0 && a[i] == a[i-1] && !used[i-1]) continue;        // duplicate guard
        used[i] = true; path.push_back(a[i]);
        permute(a, used, path, out);
        path.pop_back(); used[i] = false;
    }
}

// Constraint placement (N-Queens): one decision per row, prune with O(1) attack checks.
void queens(int r, int n, vector<int>& col, vector<bool>& usedCol, vector<bool>& d1, vector<bool>& d2, int& count) {
    if (r == n) { ++count; return; }
    for (int c = 0; c < n; ++c) {
        if (usedCol[c] || d1[r + c] || d2[r - c + n - 1]) continue;  // prune
        usedCol[c] = d1[r + c] = d2[r - c + n - 1] = true; col[r] = c;
        queens(r + 1, n, col, usedCol, d1, d2, count);
        usedCol[c] = d1[r + c] = d2[r - c + n - 1] = false;
    }
}
